CREATE TABLE IF NOT EXISTS notification_preferences(user_id BIGINT UNSIGNED PRIMARY KEY,push_booking TINYINT NOT NULL DEFAULT 1,push_reminder TINYINT NOT NULL DEFAULT 1,push_delay TINYINT NOT NULL DEFAULT 1,push_waitlist TINYINT NOT NULL DEFAULT 1,push_announcement TINYINT NOT NULL DEFAULT 1,sms_reminder TINYINT NOT NULL DEFAULT 1,sms_delay TINYINT NOT NULL DEFAULT 1,sms_waitlist TINYINT NOT NULL DEFAULT 1,sms_announcement TINYINT NOT NULL DEFAULT 1,push_consent_at DATETIME NULL,sms_consent_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS push_subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,endpoint TEXT NOT NULL,endpoint_hash CHAR(64) NOT NULL UNIQUE,p256dh VARCHAR(120) NOT NULL,auth VARCHAR(40) NOT NULL,user_agent VARCHAR(190) NOT NULL DEFAULT '',active TINYINT NOT NULL DEFAULT 1,failures TINYINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_used_at DATETIME NULL,INDEX push_user(user_id,active),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS push_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT UNSIGNED NOT NULL,notification_id BIGINT UNSIGNED NULL,payload TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'queued',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,next_attempt_at DATETIME NULL,http_status SMALLINT NULL,error VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,INDEX push_queue(status,next_attempt_at),FOREIGN KEY(subscription_id) REFERENCES push_subscriptions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS waitlist_entries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,family_member_id BIGINT UNSIGNED NULL,patient_name VARCHAR(190) NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,clinic_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,date_from DATE NOT NULL,date_to DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'waiting',last_notified_at DATETIME NULL,notify_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,booking_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,INDEX waitlist_clinic(clinic_id,status,id),INDEX waitlist_user(user_id,status),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(clinic_id) REFERENCES clinics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS clinic_queues(clinic_id BIGINT UNSIGNED NOT NULL,day DATE NOT NULL,last_number SMALLINT UNSIGNED NOT NULL DEFAULT 0,current_number SMALLINT UNSIGNED NULL,current_booking_id BIGINT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(clinic_id,day),FOREIGN KEY(clinic_id) REFERENCES clinics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
